        ".rs-sky{position:absolute;left:0;right:0;top:0;height:20%;background:linear-gradient(#7fbde6 0%,rgba(150,205,238,.85) 45%,rgba(190,224,244,0) 100%);pointer-events:none}",
        ".rs-cloud{position:absolute;display:block;background:#fff;border-radius:999px;opacity:.92;box-shadow:0 2px 6px rgba(80,130,170,.18)}",
        ".rs-cloud::before,.rs-cloud::after{content:'';position:absolute;background:#fff;border-radius:50%}",
