  // 人物站的高度：涼亭平台與階梯
  function rsGroundY(x, z) {
    let g = gt.gazebo,
      h = g.w / 2;
    if (Math.abs(z - g.z) >= h) return 0;
    if (Math.abs(x - g.x) < h) return g.deckH;
    let ex = g.x - h; // 東側階梯
    if (x < ex && x >= ex - 0.32) return (g.deckH * 2) / 3;
    if (x < ex - 0.32 && x >= ex - 0.64) return g.deckH / 3;
    if (x < ex - 0.64 && x >= ex - 0.98) return 0.06;
    return 0;
  }
  // ---------- 遊戲區 ----------
